package com.autocare.platform.order;
import com.autocare.platform.gateway.identity.*;
import com.autocare.platform.common.write.WriteIntegrityService;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import static org.junit.jupiter.api.Assertions.*;

class JdbcExperienceCurationsTest extends JdbcExperienceDetailTest {
 ExperienceCurations curations;OperatorActor curator;Time clock;
 static class Time extends Clock{Instant value=Instant.now().truncatedTo(java.time.temporal.ChronoUnit.SECONDS);public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return Clock.fixed(value,z);}public Instant instant(){return value;}}
 @BeforeEach void curate(TestInfo info){jdbc.execute("DROP TRIGGER IF EXISTS fail_curation_audit");jdbc.update("DELETE FROM experience_curation");if(info.getTestMethod().orElseThrow().getDeclaringClass()!=JdbcExperienceCurationsTest.class)return;clock=new Time();var manager=new DataSourceTransactionManager(jdbc.getDataSource());db=new ReservationStore(jdbc,db.mapper,new WriteIntegrityService(jdbc,db.mapper,manager),clock,manager);curator=operator();jdbc.update("UPDATE operator_account SET can_community_curate=1 WHERE id=1");curations=new ExperienceCurations(db,new OperatorIdentity(jdbc,null,manager),moderation(true));}
 @AfterEach void clean(){jdbc.execute("DROP TRIGGER IF EXISTS fail_curation_audit");}
 ObjectNode body(String id,int priority){var page=db.mapper.valueToTree(curations.sources(curator,1));String hash=null;for(var item:page.path("items"))if(id.equals(item.path("experience").path("experience_id").asText()))hash=item.path("source_hash").asText();assertNotNull(hash);return db.mapper.createObjectNode().put("experience_id",id).put("source_hash",hash).put("priority",priority).put("source_note","secret synthetic source label").put("scope_confirmed",true).put("valid_from",clock.value.plusSeconds(3600).toString()).put("valid_to",clock.value.plusSeconds(7200).toString());}
 long create(ObjectNode b){ExperienceCurations.input(b.toString(),false);return curations.create(curator,key(),b).path("data").path("id").asLong();}
 void publish(long id){curations.status(curator,id,key(),db.mapper.createObjectNode().put("expected_revision",1).put("status","PUBLISHED"));}
 com.fasterxml.jackson.databind.JsonNode hot(){return db.mapper.valueToTree(curations.curated(other,2));}
 @Test void currentPermissionAndOnlyPublicTrustedCandidatesAreRequired(){String id=approved();assertEquals(1,db.mapper.valueToTree(curations.sources(curator,1)).path("items").size());jdbc.update("UPDATE operator_account SET can_community_curate=0 WHERE id=1");assertEquals(403,status(()->curations.list(curator,1)));assertEquals(403,status(()->curations.sources(curator,1)));jdbc.update("UPDATE operator_account SET can_community_curate=1,can_review=0 WHERE id=1");var confirmed=body(id,2);long c=create(body(id,1));assertNotNull(curations.detail(curator,c));jdbc.update("UPDATE file_object SET scan_status='INFECTED' WHERE id=101");assertTrue(((List<?>)curations.sources(curator,1).get("items")).isEmpty());assertEquals(404,status(()->curations.create(curator,key(),confirmed)));}
 @Test void exactSourceConfirmationCasAndPublishedFreeze(){String id=approved();var b=body(id,3);long c=create(b);curations.update(curator,c,key(),b.deepCopy().put("priority",2).put("expected_revision",1));assertEquals(409,status(()->curations.update(curator,c,key(),b.deepCopy().put("expected_revision",1))));curations.status(curator,c,key(),db.mapper.createObjectNode().put("expected_revision",2).put("status","PUBLISHED"));assertEquals(409,status(()->curations.update(curator,c,key(),b.deepCopy().put("expected_revision",3))));for(var invalid:List.of(b.deepCopy().put("priority",0),b.deepCopy().put("priority",1.0),b.deepCopy().put("scope_confirmed",false),b.deepCopy().put("source_note",""),b.deepCopy().put("user_id",1)))assertThrows(Exception.class,()->ExperienceCurations.input(invalid.toString(),false));assertThrows(Exception.class,()->ExperienceCurations.input(b+"{}",false));}
 @Test void windowBoundariesReadOnlyScopeAndNoPrivateSourceText(){String id=approved();assertEquals("UNKNOWN",hot().path("state").asText());long c=create(body(id,1));publish(c);assertEquals("UNKNOWN",hot().path("state").asText());clock.value=instant(curations.row(c,false).get("valid_from"));int audits=count("audit_log"),writes=count("idempotency_record");var view=hot();assertEquals("CONFIGURED",view.path("state").asText());assertEquals("OPERATOR_CURATED",view.path("selection_type").asText());assertEquals(1,view.path("items").size());for(String k:List.of("secret synthetic source label","source_hash","source_note","submission_key","order_id","views","heat"))assertFalse(view.toString().contains(k));assertEquals(audits,count("audit_log"));assertEquals(writes,count("idempotency_record"));assertEquals(404,status(()->curations.curated(owner,2)));jdbc.update("UPDATE vehicle SET model_id=2 WHERE id=2");assertEquals("UNKNOWN",hot().path("state").asText());jdbc.update("UPDATE vehicle SET model_id=1 WHERE id=2");clock.value=instant(curations.row(c,false).get("valid_to"));assertEquals("UNKNOWN",hot().path("state").asText());}
 @Test void withdrawalInvalidSourcesAndStoppedRowsNeverFallBack(){String id=approved();long c=create(body(id,1));publish(c);clock.value=instant(curations.row(c,false).get("valid_from"));assertEquals(1,hot().path("items").size());cards().change(owner,cardId,key(),db.mapper.createObjectNode(),false);assertEquals("UNKNOWN",hot().path("state").asText());curations.status(curator,c,key(),db.mapper.createObjectNode().put("expected_revision",2).put("status","STOPPED"));assertEquals("STOPPED",curations.row(c,false).get("status"));assertNotNull(curations.detail(curator,c).get("source_snapshot"));assertEquals(409,status(()->curations.status(curator,c,key(),db.mapper.createObjectNode().put("expected_revision",3).put("status","PUBLISHED"))));}
 @Test void originalPublicationProofTamperingSoftDeleteAndOldRowRollbackAreRejected(){String id=approved();long c=create(body(id,1));publish(c);clock.value=instant(curations.row(c,false).get("valid_from"));jdbc.update("UPDATE experience_curation SET priority=2 WHERE id=?",c);assertEquals("UNKNOWN",hot().path("state").asText());jdbc.update("UPDATE experience_curation SET priority=1 WHERE id=?",c);jdbc.update("UPDATE audit_log SET is_deleted=1 WHERE action='CURATION_STATUS'");assertEquals("UNKNOWN",hot().path("state").asText());jdbc.update("UPDATE audit_log SET is_deleted=0 WHERE action='CURATION_STATUS'");curations.status(curator,c,key(),db.mapper.createObjectNode().put("expected_revision",2).put("status","STOPPED"));jdbc.update("UPDATE experience_curation SET status='PUBLISHED',revision=2,stopped_at=NULL WHERE id=?",c);assertEquals("UNKNOWN",hot().path("state").asText());}
 @Test void permanentOriginalReceiptSurvivesExpiryAndSourceLossButReauthorizes(){String id=approved();var b=body(id,1);String k=key();var first=curations.create(curator,k,b);long c=first.path("data").path("id").asLong();publish(c);cards().change(owner,cardId,key(),db.mapper.createObjectNode(),false);clock.value=clock.value.plusSeconds(10000);jdbc.update("UPDATE idempotency_record SET expires_at=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 2 DAY)");assertEquals(first.path("data"),curations.create(curator,k,b).path("data"));jdbc.update("UPDATE idempotency_record SET expires_at=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 2 DAY)");assertEquals(400,status(()->curations.create(curator,k,b.deepCopy().put("priority",2))));assertEquals(1,count("experience_curation"));jdbc.update("UPDATE operator_account SET can_community_curate=0 WHERE id=1");assertEquals(403,status(()->curations.create(curator,k,b)));}
 @Test void auditFailuresRollBackCreationAndPublicationAndDisabledFlagIsExplicit(){String id=approved();var b=body(id,1);jdbc.execute("CREATE TRIGGER fail_curation_audit BEFORE INSERT ON audit_log FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic failure'");assertEquals(503,status(()->curations.create(curator,key(),b)));assertEquals(0,count("experience_curation"));jdbc.execute("DROP TRIGGER fail_curation_audit");long c=create(b);jdbc.execute("CREATE TRIGGER fail_curation_audit BEFORE INSERT ON audit_log FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic failure'");assertEquals(503,status(()->publish(c)));assertEquals("DRAFT",curations.row(c,false).get("status"));var disabled=new ExperienceCurations(db,new OperatorIdentity(jdbc,null,new DataSourceTransactionManager(jdbc.getDataSource())),moderation(false));assertEquals("UNAVAILABLE",disabled.curated(other,2).get("state"));}
 @Test void twoOperatorsCannotPublishTwoCurationsForOnePublicExperience()throws Exception{String id=approved();long one=create(body(id,1)),two=create(body(id,2));jdbc.update("INSERT INTO operator_account(id,account,password_hash,phone,can_community_curate) VALUES(2,'synthetic-curator','unused','13800000001',1)");String session=key();jdbc.update("INSERT INTO auth_session(id,subject_type,subject_id,role,app_id,refresh_hash,expires_at) VALUES(?,'operator_account',2,'OPERATOR','operator-account',?,DATE_ADD(UTC_TIMESTAMP(),INTERVAL 1 HOUR))",session,key());var peer=new OperatorActor(2,session,Instant.now().plusSeconds(600));var start=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->{start.await();try{publish(one);return 200;}catch(org.springframework.web.server.ResponseStatusException e){return e.getStatusCode().value();}});var b=pool.submit(()->{start.await();try{curations.status(peer,two,key(),db.mapper.createObjectNode().put("expected_revision",1).put("status","PUBLISHED"));return 200;}catch(org.springframework.web.server.ResponseStatusException e){return e.getStatusCode().value();}});start.countDown();var codes=new ArrayList<>(List.of(a.get(30,TimeUnit.SECONDS),b.get(30,TimeUnit.SECONDS)));Collections.sort(codes);assertEquals(List.of(200,409),codes);}finally{pool.shutdownNow();}}
 @Test void withdrawalAndPublicationSerializeWithoutExposingWithdrawnCuration()throws Exception{String id=approved();long c=create(body(id,1));var start=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{var pub=pool.submit(()->{start.await();try{publish(c);return 200;}catch(org.springframework.web.server.ResponseStatusException e){return e.getStatusCode().value();}});var withdraw=pool.submit(()->{start.await();cards().change(owner,cardId,key(),db.mapper.createObjectNode(),false);return 200;});start.countDown();assertTrue(List.of(200,404).contains(pub.get(30,TimeUnit.SECONDS)));assertEquals(200,withdraw.get(30,TimeUnit.SECONDS));clock.value=clock.value.plusSeconds(3600);assertEquals("UNKNOWN",hot().path("state").asText());}finally{pool.shutdownNow();}}
 String additionalSource(int order){jdbc.update("INSERT INTO `order`(id,order_no,user_id,vehicle_id,merchant_id,amount,pay_amount,status,service_report_ready_at) VALUES(?,?,1,1,1,10,10,'COMPLETED',UTC_TIMESTAMP())",order,"synthetic-curated-"+order);jdbc.update("INSERT INTO payment(id,order_id,channel,payment_no,currency,amount,status,paid_at,channel_payment_no) VALUES(?,?,'WECHAT',?,'CNY',10,'SUCCEEDED',UTC_TIMESTAMP(),?)",order,order,"curated-payment-"+order,"curated-channel-"+order);jdbc.update("INSERT INTO payment_event(channel,event_id,payment_id,event_hash,outcome) VALUES('WECHAT',?,?,?,'PAID')",key(),order,"a".repeat(64));jdbc.update("INSERT INTO order_redemption(id,order_id,merchant_id,staff_id,payment_id,test_mode,redeemed_at) VALUES(?,?,1,1,?,0,UTC_TIMESTAMP())",order,order,order);jdbc.update("INSERT INTO technician_report(id,order_id,technician_id,process_photos,fault_part_photos,finish_photos,repair_plan,fault_analysis,parts_used,work_hours,status,signed_at) VALUES(?,?,2,?,'[]',?,'检查与清洁','未发现需更换故障件','[]',40,1,'2026-10-09 01:00:00')",order,order,"["+(order*100+1)+"]","["+(order*100+2)+"]");jdbc.update("INSERT INTO service_report_submission(order_id,report_id,no_parts,no_fault_parts,submitted_at) VALUES(?,?,1,1,'2026-10-09 00:50:00')",order,order);for(int slot=1;slot<=3;slot++){int file=order*100+slot;jdbc.update("INSERT INTO file_object(id,owner_type,owner_id,object_key,content_type,size_bytes,scan_status) VALUES(?,'staff_account',2,?,'image/png',100,'CLEAN')",file,"curated-file-"+file);jdbc.update("INSERT INTO service_evidence_file(order_id,record_id,file_id,kind) VALUES(?,?,?,?)",order,order,file,slot==1?"PROCESS":slot==2?"FINISH":"SIGNATURE");}new OrderReviews(db).submit(owner,key(),db.mapper.valueToTree(Map.of("order_id",order,"rating",5,"content","施工反馈","photo_file_ids",List.of())));long job=jdbc.queryForObject("SELECT id FROM service_archive_job WHERE order_id=?",Long.class,order);new ServiceArchiveJobs(db,true,true).consume(job);long card=jdbc.queryForObject("SELECT id FROM experience_card WHERE order_id=?",Long.class,order);cards().change(owner,card,key(),consent(),true);moderation(true).moderate(curator,card,key(),decision(1,true));return jdbc.queryForObject("SELECT public_id FROM experience_card_moderation WHERE card_id=?",String.class,card);}
 @Test void configuredPriorityAndNewestTieOrderRealApprovedSources(){String first=approved(),second=additionalSource(2),third=additionalSource(3);long a=create(body(first,20)),b=create(body(second,10)),c=create(body(third,10));publish(a);publish(b);publish(c);clock.value=instant(curations.row(a,false).get("valid_from"));var items=hot().path("items");assertEquals(3,items.size());assertEquals(List.of(third,second,first),java.util.stream.StreamSupport.stream(items.spliterator(),false).map(n->n.path("experience").path("experience_id").asText()).toList());}
 static Instant instant(Object n){return ReservationStore.instant(n);}
}
